import React from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { useApp } from '../context/AppContext';

const Sidebar = () => {
  const { sidebarOpen, setSidebarOpen } = useApp();
  const navigate = useNavigate();

  const close = () => setSidebarOpen(false);

  const handleUpload = () => {
    close();
    navigate('/upload');
  };

  return (
    <>
      <div
        className={`sidebar-overlay ${sidebarOpen ? 'active' : ''}`}
        onClick={close}
      />
      <aside className={`sidebar ${sidebarOpen ? 'open' : ''}`}>
        {/* Logo */}
        <div className="sidebar-logo">
          <span className="sidebar-logo-icon">🌱</span>
          <div className="sidebar-logo-text">
            <span>ECOISTIC</span>
            <span>GROW GREEN TOGETHER</span>
          </div>
        </div>

        {/* Nav */}
        <nav className="sidebar-nav">
          <NavLink to="/" className={({ isActive }) => isActive ? 'active' : ''} onClick={close}>
            <span className="nav-icon">🏠</span>
            Home
          </NavLink>
          <NavLink to="/history" className={({ isActive }) => isActive ? 'active' : ''} onClick={close}>
            <span className="nav-icon">🏆</span>
            Success History
          </NavLink>
          <NavLink to="/about" className={({ isActive }) => isActive ? 'active' : ''} onClick={close}>
            <span className="nav-icon">🌿</span>
            About Us
          </NavLink>
          <button onClick={handleUpload}>
            <span className="nav-icon">📤</span>
            Upload
          </button>
          <NavLink to="/settings" className={({ isActive }) => isActive ? 'active' : ''} onClick={close}>
            <span className="nav-icon">⚙️</span>
            Settings
          </NavLink>
        </nav>

        {/* Planter illustration */}
        <div className="sidebar-planter">
          <svg className="planter-svg" viewBox="0 0 140 110" fill="none" xmlns="http://www.w3.org/2000/svg">
            {/* Ground */}
            <ellipse cx="70" cy="95" rx="55" ry="10" fill="#2d4a1e" opacity="0.4"/>
            {/* Person body */}
            <circle cx="70" cy="30" r="14" fill="#f5cba7"/>
            {/* Hair */}
            <ellipse cx="70" cy="20" rx="13" ry="8" fill="#3d1a00"/>
            {/* Shirt */}
            <path d="M50 60 Q55 45 70 43 Q85 45 90 60 L88 80 L52 80 Z" fill="#2d6a4f"/>
            {/* Arms */}
            <path d="M50 60 Q38 70 32 80" stroke="#f5cba7" strokeWidth="7" strokeLinecap="round"/>
            <path d="M90 60 Q100 68 104 78" stroke="#f5cba7" strokeWidth="7" strokeLinecap="round"/>
            {/* Hands holding soil */}
            <circle cx="30" cy="82" r="7" fill="#f5cba7"/>
            <circle cx="106" cy="80" r="7" fill="#f5cba7"/>
            {/* Soil mound */}
            <ellipse cx="70" cy="90" rx="30" ry="12" fill="#5d4037"/>
            <ellipse cx="70" cy="85" rx="22" ry="10" fill="#6d4c41"/>
            {/* Plant sapling */}
            <line x1="70" y1="85" x2="70" y2="55" stroke="#388e3c" strokeWidth="3"/>
            <ellipse cx="60" cy="62" rx="10" ry="6" fill="#4caf50" transform="rotate(-20 60 62)"/>
            <ellipse cx="80" cy="58" rx="10" ry="6" fill="#66bb6a" transform="rotate(15 80 58)"/>
            <ellipse cx="70" cy="52" rx="8" ry="5" fill="#81c784" transform="rotate(-5 70 52)"/>
            {/* Legs */}
            <path d="M58 80 L54 98 L60 98 L64 80" fill="#1a3a2e"/>
            <path d="M82 80 L86 98 L80 98 L76 80" fill="#1a3a2e"/>
          </svg>
          <p>Every Plant<br/>Makes a Difference 🌿</p>
        </div>
      </aside>
    </>
  );
};

export default Sidebar;
